{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Nipradilol absolute extent of bioavailability was 0.32 ± 0.03 in younger subjects after a 6 mg oral dose, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Vinorelbine absolute oral bioavailability was 37.8 ± 14.0% in patients at 80 mg/m2 oral versus IV, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Maraviroc absolute oral bioavailability was 33% in healthy volunteers at a 300 mg oral dose, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules have absolute oral bioavailability values or qualitative assessments at or above 20%; numeric absolute measurements in healthy/patient populations consistently support high bioavailability. No molecule-level evidence supports F < 20%.",
  "evidence_gaps": [
    "Some records show wide interindividual ranges with lower bounds below 20% (e.g., encainide 7–82%, vinorelbine 6–130%, ketanserin 15–60%), but the strongest numeric absolute records have means and lower bounds above 20%.",
    "A few records are qualitative (stavudine, mericitabine) or from altered populations (cirrhosis, hepatic disease); these were discounted relative to numeric ordinary-condition measurements.",
    "Naldemedine is only estimated at 20–56%, with the lower bound at the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

